create extension if not exists pgcrypto;
create table if not exists public.departments(id bigint generated by default as identity primary key,name text unique not null);
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'user',department_id bigint references public.departments(id),created_at timestamptz default now());
create table if not exists public.rulebook_entries(id bigint generated by default as identity primary key,rulebook_number bigint generated always as identity unique,user_id uuid references auth.users(id) on delete set null,name text not null,designation text,department_id bigint references public.departments(id),mistake_title text not null,project_name text,finding text not null,learning text not null,solution text not null,mistake_date date default current_date,status text default 'active',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.case_studies(id bigint generated by default as identity primary key,rulebook_entry_id bigint unique not null references public.rulebook_entries(id) on delete cascade,title text not null,summary text,created_at timestamptz default now());
insert into public.departments(name) values ('Sales'),('Marketing'),('DGM / Digital'),('Operations'),('Projects'),('Procurement'),('Admin'),('Accounts') on conflict(name) do nothing;
alter table public.departments enable row level security; alter table public.profiles enable row level security; alter table public.rulebook_entries enable row level security; alter table public.case_studies enable row level security;
create policy "auth read departments" on public.departments for select to authenticated using(true);
create policy "auth read profiles" on public.profiles for select to authenticated using(true);
create policy "own profile update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "auth read rulebook" on public.rulebook_entries for select to authenticated using(true);
create policy "auth insert rulebook" on public.rulebook_entries for insert to authenticated with check(user_id=auth.uid());
create policy "own rulebook update" on public.rulebook_entries for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "auth read cases" on public.case_studies for select to authenticated using(true);
create policy "auth insert cases" on public.case_studies for insert to authenticated with check(true);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
